begin;
create extension if not exists pgtap with schema extensions;
select plan(10);
insert into auth.users(id,email) values ('81111111-1111-1111-1111-111111111111','friend-a@example.test'),('82222222-2222-2222-2222-222222222222','friend-b@example.test');
insert into public.profiles(id,owner_id,display_name) values ('8aaaaaaa-1111-1111-1111-111111111111','81111111-1111-1111-1111-111111111111','A'),('8bbbbbbb-2222-2222-2222-222222222222','82222222-2222-2222-2222-222222222222','B');
set local role authenticated;
select set_config('request.jwt.claim.sub','81111111-1111-1111-1111-111111111111',true);
select throws_ok($$select public.mutate_friendship('8aaaaaaa-1111-1111-1111-111111111111','send',gen_random_uuid(),0)$$,'22023',null,'self request denied');
select is(public.mutate_friendship('8bbbbbbb-2222-2222-2222-222222222222','send','80000000-0000-0000-0000-000000000001',0)->>'state','pending','send is pending');
select throws_ok($$select public.mutate_friendship('8bbbbbbb-2222-2222-2222-222222222222','accept',gen_random_uuid(),1)$$,'42501',null,'sender cannot accept');
select set_config('request.jwt.claim.sub','82222222-2222-2222-2222-222222222222',true);
select is(public.mutate_friendship('8aaaaaaa-1111-1111-1111-111111111111','send',gen_random_uuid(),0)->>'state','pending','crossed send does not auto-accept');
select is(public.mutate_friendship('8aaaaaaa-1111-1111-1111-111111111111','decline',gen_random_uuid(),1)->>'state','none','recipient declines');
select set_config('request.jwt.claim.sub','81111111-1111-1111-1111-111111111111',true);
select is(public.mutate_friendship('8bbbbbbb-2222-2222-2222-222222222222','send',gen_random_uuid(),2)->>'version','3','new request after decline');
select set_config('request.jwt.claim.sub','82222222-2222-2222-2222-222222222222',true);
select is(public.mutate_friendship('8aaaaaaa-1111-1111-1111-111111111111','accept',gen_random_uuid(),3)->>'state','accepted','recipient accepts');
select is(public.mutate_friendship('8aaaaaaa-1111-1111-1111-111111111111','remove',gen_random_uuid(),4)->>'state','none','participant removes friend');
select set_config('request.jwt.claim.sub','81111111-1111-1111-1111-111111111111',true);
select public.mutate_friendship('8bbbbbbb-2222-2222-2222-222222222222','send','80000000-0000-0000-0000-000000000001',0);
select is(public.get_friendship('8bbbbbbb-2222-2222-2222-222222222222')->>'state','none','historical retry cannot recreate removed request');
select throws_ok($$select * from public.friendships$$,'42501',null,'raw relationship access denied');
select * from finish();
rollback;
